# Custom inline SVG illustrations (no emoji, no external assets).
G='''<defs><linearGradient id="{id}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#A78BFA"/><stop offset="1" stop-color="#6D28D9"/></linearGradient></defs>'''
def svg(id, body, vb="0 0 96 96", cls="ill"):
    return f'<svg class="{cls}" viewBox="{vb}" aria-hidden="true" focusable="false">{G.format(id=id)}<rect x="4" y="4" width="88" height="88" rx="26" fill="#F1EBFF"/>{body.replace("GRAD","url(#"+id+")")}</svg>'
