def phone(id, rows):  # mini phone screen showing a settings path with an "allow" toggle
    y=22; body='<rect x="30" y="6" width="60" height="108" rx="12" fill="#1d1636"/><rect x="34" y="12" width="52" height="96" rx="8" fill="#fff"/>'
    for i,(w,on) in enumerate(rows):
        body+=f'<rect x="38" y="{y}" width="{w}" height="7" rx="3.5" fill="{"#7C3AED" if on is None else "#E7DEFF"}"/>'
        if on is not None:
            body+=f'<rect x="68" y="{y-1}" width="14" height="9" rx="4.5" fill="{"url(#"+id+")" if on else "#D9D3EA"}"/><circle cx="{77.5 if on else 72.5}" cy="{y+3.5}" r="3.2" fill="#fff"/>'
        y+=15
    return f'<svg class="mini" viewBox="0 0 120 120" aria-hidden="true" focusable="false">{G.format(id=id)}{body}</svg>'
